Dataspatium.assets.register("presets/api/luftkvalitet.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"luftkvalitet\",\n  \"name\": \"Luftkvalitet (Naturvårdsverkets datavärdskap)\",\n  \"publisher\": \"Naturvårdsverket, datavärd SMHI\",\n  \"description\": \"Mätningar av luftföroreningar (NO2, PM10, PM2.5, ozon med mera) från Sveriges mätstationer. Lista stationer och tidsserier, hämta sedan värden för en tidsserie och ett tidsintervall.\",\n  \"docs\": \"https://datavardluft.smhi.se/\",\n  \"license\": { \"name\": \"Öppna data, se datavärdskapets villkor\", \"url\": \"https://datavardluft.smhi.se/\" },\n  \"level\": 1,\n  \"baseUrl\": \"https://datavardluft.smhi.se/52North/api\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 10, \"perSeconds\": 2 },\n  \"endpoints\": [\n    {\n      \"id\": \"stations\",\n      \"name\": \"Mätstationer\",\n      \"method\": \"GET\",\n      \"path\": \"/stations\",\n      \"params\": [\n        { \"name\": \"expanded\", \"in\": \"query\", \"type\": \"string\", \"default\": \"true\", \"hidden\": true }\n      ],\n      \"response\": { \"format\": \"geojson\", \"options\": { \"geometry\": false }, \"rename\": { \"label\": \"station\", \"classification\": \"klassning\", \"id\": \"station_id\" } },\n      \"dataset\": { \"name\": \"Luftkvalitet mätstationer\" }\n    },\n    {\n      \"id\": \"timeseries\",\n      \"name\": \"Tidsserier\",\n      \"description\": \"Alla tidsserier med station, ämne, enhet och period. Kolumnen id används för att hämta värden.\",\n      \"method\": \"GET\",\n      \"path\": \"/timeseries\",\n      \"params\": [\n        { \"name\": \"station\", \"in\": \"query\", \"label\": \"Station (id, valfritt)\", \"type\": \"string\" },\n        { \"name\": \"phenomenon\", \"in\": \"query\", \"label\": \"Ämne (id, valfritt)\", \"type\": \"string\" },\n        { \"name\": \"expanded\", \"in\": \"query\", \"type\": \"string\", \"default\": \"true\", \"hidden\": true }\n      ],\n      \"response\": { \"format\": \"json\", \"convert\": { \"firstValue.timestamp\": \"epoch-ms\", \"lastValue.timestamp\": \"epoch-ms\" }, \"rename\": { \"label\": \"tidsserie\", \"uom\": \"enhet\", \"station.properties.label\": \"station\", \"station.id\": \"station_id\", \"parameters.phenomenon.label\": \"amne\", \"parameters.phenomenon.id\": \"amne_id\", \"firstValue.timestamp\": \"forsta_tid\", \"lastValue.timestamp\": \"senaste_tid\", \"firstValue.value\": \"forsta_varde\", \"lastValue.value\": \"senaste_varde\" }, \"drop\": [\"extras\", \"aggregationTypes\", \"station.type\", \"station.geometry.type\", \"station.properties.classification\", \"parameters.procedure.id\", \"parameters.procedure.label\", \"parameters.category.id\", \"parameters.category.label\", \"parameters.offering.id\", \"parameters.offering.label\", \"parameters.feature.id\", \"parameters.feature.label\", \"parameters.service.id\", \"parameters.service.label\", \"renderingHints\", \"statusIntervals\"] },\n      \"dataset\": { \"name\": \"Luftkvalitet tidsserier\" }\n    },\n    {\n      \"id\": \"data\",\n      \"name\": \"Värden för en tidsserie\",\n      \"method\": \"GET\",\n      \"path\": \"/timeseries/{id}/getData\",\n      \"params\": [\n        { \"name\": \"id\", \"in\": \"path\", \"label\": \"Tidsserie (id från listan Tidsserier)\", \"type\": \"string\", \"required\": true, \"example\": \"78\" },\n        { \"name\": \"timespan\", \"in\": \"query\", \"label\": \"Tidsintervall (ISO 8601)\", \"type\": \"string\", \"required\": true, \"example\": \"2024-01-01T00:00:00Z/2024-01-31T23:00:00Z\", \"help\": \"Start/slut, eller en längd och en sluttid som PT24H/2026-11-02T00:00:00Z.\" }\n      ],\n      \"response\": { \"format\": \"json\", \"path\": \"values\", \"convert\": { \"timestamp\": \"epoch-ms\" }, \"rename\": { \"timestamp\": \"tid\", \"value\": \"varde\" } },\n      \"dataset\": { \"name\": \"Luftkvalitet tidsserie {id}\", \"keys\": [\"tid\"] }\n    }\n  ]\n}\n");
